var s=[{title:`Cuánto dura la recuperación`,text:`Depende del ejercicio, del volumen total, de la intensidad, del sueño, de la forma física y de lo familiar que te resulte el trabajo. Después de una sesión dura para un grupo muscular grande, unas 48–72 horas antes de otra sesión igual de dura es una pauta habitual de planificación. Es una orientación, y algunas personas necesitan más o menos.`},{title:`Señales de que no te has recuperado`,text:`Unas agujetas que duran más de lo habitual, menos repeticiones con la misma carga, piernas pesadas, poca motivación y cambios en tu técnica pueden indicar demasiada fatiga. Una mala sesión no demuestra sobreentrenamiento. Busca tendencias a lo largo de varios entrenamientos, sobre todo si además duermes mal, estás enfermo o tienes más estrés en el resto de tu vida.`},{title:`Reparte el trabajo duro`,text:`Una semana típica podría tener fuerza de cuerpo completo el lunes y el jueves, con paseos suaves los demás días. Entrenar la fuerza con más frecuencia puede funcionar cuando repartes los ejercicios o los grupos musculares a lo largo de la semana y mantienes el volumen bajo control. El cardio suave o la movilidad en un día sin pesas suelen encajar bien con la recuperación.`},{title:`Ayuda a tu cuerpo a adaptarse`,text:`Procura dormir con regularidad, comer y beber lo suficiente, hacer pequeños aumentos de entrenamiento y descansar los días que lo necesites. Las agujetas no son una puntuación de lo bueno que fue el entrenamiento. Si tu rendimiento sigue bajando, reduce el volumen, elige variantes más fáciles o añade tiempo de recuperación. No subas la intensidad para compensarlo.`},{title:`Cómo usar TrainUp`,text:`Después de cada entrenamiento, valora tu esfuerzo e indica cualquier dolor o molestia. Cuando vuelves a generar el plan, TrainUp mira al menos 3 entrenamientos. Cualquier dolor reciente significa que no hay aumento. Si 2 de tus últimos 3 entrenamientos fueron muy duros (RPE 9 o más) o se completaron en menos de un 60 %, el siguiente plan es más fácil. Historial muestra tu esfuerzo medio y un gráfico de 4 semanas. Si los síntomas graves persisten, busca consejo médico.`}];var n=[{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: dosis de ejercicio, recuperación y progresión`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`NHS: agujetas de aparición tardía`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var o={sections:s,sources:n};export{o as default,s as sections,n as sources};